import{d as g,C as e,o as h,c as d,a3 as t,E as i,j as n,a as p}from"./chunks/framework.Q4yG9rk_.js";const b=JSON.parse('{"title":"正易心法·第一章","description":"《正易心法》第一章——「落处」为全书纲领：卦画本身即自然现象的直接写照，学《易》须知卦画实义，不作纸上功夫。","frontmatter":{"title":"正易心法·第一章","description":"《正易心法》第一章——「落处」为全书纲领：卦画本身即自然现象的直接写照，学《易》须知卦画实义，不作纸上功夫。","category":"guide","aliases":["正易心法第一章","落处","羲皇易道"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-01.md","filePath":"yijing/zheng-yi-xin-fa/chapter-01.md","lastUpdated":1790647676000}'),u={name:"yijing/zheng-yi-xin-fa/chapter-01.md"},x=g({...u,setup(c){const o=[{id:"z1-01",label:"一、须知落处",showLabel:!0,sentences:[[{text:"羲皇",glossary:"xiHuang"},{text:"《易》道",glossary:"yidao"},"，包括万象。须知",{text:"落处",glossary:"luochu"},"，方可实用。"]],note:["伏羲所画的《易》道，涵盖天地万象；但必须知道它的「落处」，才能真正实用。"]},{id:"z1-02",label:"二、落处谓何",showLabel:!0,sentences:[["落处，谓知",{text:"卦画",glossary:"guahua"},"实义所在，不",{text:"盲诵",glossary:"mangSong"},"古人语也。"]],note:["所谓「落处」，是指知道每一卦画的真实义理所在，而不是盲目背诵古人的文字解说。「落处」是本章的核心词：不是空间的「落脚处」，而是义理最终兑现、对应到实象的那个点——禅宗语录里问「这一句话落处在哪里」，问的就是这个。"]},{id:"z1-03",label:"三、震坎艮得乾爻",showLabel:!0,sentences:[["如震得乾初爻，故雷自天下而发；坎得中爻，故月自天之中而运；艮得上爻，故山自天上而坠也；巽、离、兑得坤三爻亦然。"]],note:["比如震（☳）得一阳在最下，所以雷从天的下方发出；坎（☵）得一阳在中间，所以月亮在天的中间运行；艮（☶）得一阳在最上，所以山从天上坠落而成；巽、离、兑得坤之三爻（阴爻居不同位），道理一样。这里的关键不是「雷为什么响」，而是「震这一画为什么长成这样」——卦画的结构本身就在描述自然现象。"]},{id:"z1-04",label:"四、六爻与月候",showLabel:!0,sentences:[["又六爻相应，如一阳生于子月，应在卯月；二阳丑，应在三月；三阳寅，应在四月是也。"]],note:["又如六爻与月候相应：一阳生于子月（冬至，十一月），应在卯月（二月）；二阳生于丑月（十二月），应在三月；三阳生于寅月（正月），应在四月。这是「消息」——阴消阳息、阴阳进退的具体节律。"]},{id:"z1-05",label:"五、人事亦然",showLabel:!0,sentences:[["人事亦然。《易》道见于天地万物",{text:"曰用",glossary:"riyong"},"之间，能以此",{text:"消息",glossary:"xiaoxi"},"，皆得实用，方知羲皇画卦，不作",{text:"纸上功夫",glossary:"zhishang"},"也。"]],note:["人事的道理也一样。《易》道体现在天地万物的日用之间，能用这种方式去体察阴阳消长，才有真正的实用——这样才明白伏羲画卦，不是做纸上功夫。"]}],r=[{id:"xiHuang",term:"羲皇",pinyin:"xī huáng",meaning:"伏羲氏，传说中画八卦的人。书中用它指《易》的原始作者，而非文王、孔子。"},{id:"yidao",term:"《易》道",pinyin:"yì dào",meaning:"《易》所承载的道理。麻衣的用法特指卦画所呈现的自然之理，而非文字训诂。"},{id:"luochu",term:"落处",pinyin:"luò chù",meaning:"本章核心词。不是空间的「落脚处」，而是义理最终兑现、对应到实象的那个点；宋人语录常用，如「这一句话落处在哪里」。"},{id:"guahua",term:"卦画",pinyin:"guà huà",meaning:"卦的图象本身（阴阳爻线的排列），与「卦辞」相对。麻衣认为卦画是本体，文字是后加的。"},{id:"mangSong",term:"盲诵",pinyin:"máng sòng",meaning:"盲目背诵。批评只记文字、不知卦象的学习方式。"},{id:"xiaoxi",term:"消息",pinyin:"xiāo xī",meaning:"消长、进退。古义为阴消阳息，指阴阳变化的规律，非现代的「消息／信息」。"},{id:"riyong",term:"曰用",pinyin:"yuē yòng",meaning:"「曰」通「日」，日用即每日生活。谓《易》道就体现在日常之间。"},{id:"zhishang",term:"纸上功夫",pinyin:"zhǐ shàng gōng fu",meaning:"只在文字上下功夫。批评脱离卦画的文字训诂一派。"}];return(m,a)=>{const l=e("DaoTextReading"),s=e("DaoKeywordCards");return h(),d("div",null,[a[0]||(a[0]=t("",17)),i(l,{colophon:"羲皇易道 · 须知落处 · 卦画实义 · 不作纸上功夫",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第一章原文",sections:o,glossary:r}),a[1]||(a[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本（如「曰用」之「曰」、「一阳丑」等），不作统一。")],-1)),a[2]||(a[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[p("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(s,{items:[{term:"落处",pinyin:["luò","chù"],meaning:"本章核心词。不是空间的「落脚处」，而是义理最终兑现、对应到实象的那个点；宋人语录常用，如「这一句话落处在哪里」。"},{term:"卦画",pinyin:["guà","huà"],meaning:"卦的图象本身（阴阳爻线的排列），与「卦辞」相对。麻衣认为卦画是本体，文字是后加的。"},{term:"消息",pinyin:["xiāo","xī"],meaning:"消长、进退。古义为阴消阳息，指阴阳变化的规律，非现代的「消息／信息」。"},{term:"曰用",pinyin:["yuē","yòng"],meaning:"「曰」通「日」，日用即每日生活。谓《易》道就体现在日常之间。"},{term:"纸上功夫",pinyin:["zhǐ","shàng"],meaning:"只在文字上下功夫。批评脱离卦画的文字训诂一派。"}]}),a[3]||(a[3]=t("",24))])}}});export{b as __pageData,x as default};
